def calculate_factorial(n):
    if n == 0:
        return 1
    factorial = 1
    for i in range(1, n + 1):
        factorial *= i
    return factorial

def queue_using_stacks():
    stack1 = []
    stack2 = []

    def enqueue(x):
        stack1.append(x)

    def dequeue():
        if not stack2:
            while stack1:
                stack2.append(stack1.pop())
        return stack2.pop()

    return enqueue, dequeue

