class QueueUsingStacks:
    def __init__(self):
        self.push_stack = []
        self.pop_stack = []

    def enqueue(self, value):
        self.push_stack.append(value)

    def dequeue(self):
        if not self.pop_stack:
            while self.push_stack:
                self.pop_stack.append(self.push_stack.pop())
        if not self.pop_stack:
            raise IndexError('Dequeue from empty queue')
        return self.pop_stack.pop()

def enqueue(push_stack, pop_stack, element):
    if not push_stack:
        push_stack.append(element)
    else:
        temp = push_stack.pop()
        enqueue(push_stack, pop_stack, element)
        push_stack.append(temp)

    return push_stack

